import{escape,button,route}from'./ui.js';
import{originalCopy,currentLocale}from'./locale.js';
import{uiText}from'./ui-text.js';
import{contactFor}from'./chat-contact.js';
const t=communicationText;
export async function bindChatExtras(ctx,{sessionId,snapshot,refresh,onSupport}){
 const owner=await ctx.api.session();if(!ctx.active())return;
 const box=document.createElement('div');box.id='chat-extras';document.querySelector('.chat-compose').before(box);
 box.innerHTML=`<div id="chat-quick-box"><p id="chat-context"></p><div class="chat-quick-controls"><div id="chat-quick" class="inline-actions"></div><button type="button" data-action="close-quick" class="secondary" aria-label="${escape(t('close'))}">×</button></div></div><p id="chat-typing" role="status" hidden></p>`;
 let copy,contact,choices=[],sending=false,typingExpiry;
 try{
  copy=await originalCopy(ctx.signal);
  const contactId=contactFor(sessionId);
  if(contactId)contact=await ctx.api.command('chat.contact',{sessionId,contactId});
  if(!ctx.active())return;
  const keys=contact?.kind==='order'?['quickMessageOrderConsultation','quickMessageOrderShippingTime','quickMessageOrderAddressChange','quickMessageOrderProductQuestion','quickMessageOrderRefundRequest']:['quickMessageGeneralGreeting','quickMessageProductAvailable','quickMessageCanNegotiate','quickMessageWhenShip','quickMessageMoreProductImages'];
  choices=keys.map(key=>copy.t(key,contact?.kind==='order'?{orderId:contact.orderId}:{})).filter(Boolean);
  box.querySelector('#chat-context').innerHTML=contact?.kind==='product'?'<a href="'+route('/products/'+contact.productId)+'">'+escape(contact.productName)+'</a>':contact?.kind==='order'?'<a href="'+route('/orders/'+encodeURIComponent(contact.orderId))+'">'+escape(t('order'))+' '+escape(contact.orderId)+'</a>':'';
  box.querySelector('#chat-quick').innerHTML=choices.map((text,index)=>button(text,'quick-message','secondary','data-index="'+index+'"')).join('');
 }catch(e){if(ctx.active()){box.querySelector('#chat-quick-box').hidden=true;if(e.name!=='AbortError')ctx.toast(e.message);}}
 ctx.action('close-quick',()=>{box.querySelector('#chat-quick-box').hidden=true;});
 ctx.action('quick-message',async el=>{
  if(sending)return;const text=choices[Number(el.dataset.index)];if(!text)return;
  const prefix=contact?.kind==='product'?copy.t('quickMessageProductContext',{productName:contact.productName,productId:contact.productId}):'';
  sending=true;const controls=[...box.querySelector('#chat-quick').querySelectorAll('button')];controls.forEach(e=>e.disabled=true);
  try{const result=await ctx.api.command('chat.send',{sessionId,content:prefix+text});if(ctx.active()){onSupport(result);await refresh();}}
  finally{sending=false;controls.forEach(e=>{if(e.isConnected)e.disabled=false;});}
 });
 function clearTyping(){clearTimeout(typingExpiry);if(ctx.active()&&box.querySelector('#chat-typing'))box.querySelector('#chat-typing').hidden=true;}
 addEventListener('agora-buyer-realtime',event=>{
  if(!ctx.active())return;let value;try{value=JSON.parse(event.detail);}catch{return;}
  if(value.buyerId!==owner.user?.id)return;
  if(value.event==='connection.lost'||value.event==='connection.paused'){clearTyping();return;}
  const data=value.data;
  if(value.event!=='chat.typing'||data?.senderId!==snapshot()?.partnerId||data.sessionId&&data.sessionId!==sessionId)return;
  clearTyping();if(!data.active||document.visibilityState!=='visible')return;
  const label=box.querySelector('#chat-typing');label.textContent=copy?.t('chatPartnerTyping')||'對方正在輸入...';label.hidden=false;typingExpiry=setTimeout(clearTyping,5000);
 },{signal:ctx.signal});
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')clearTyping();},{signal:ctx.signal});
 ctx.cleanup(()=>clearTimeout(typingExpiry));
}

